import os, sys, json, glob, subprocess, tempfile, hashlib, time, re
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(ROOT); O = "runs/readiness-v3-20261124"; os.makedirs(O, exist_ok=True)
def sh(cmd, timeout=600): r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=timeout); return r.returncode, (r.stdout + r.stderr)
PY = ".venv/bin/python -I"; auto = []
def gate(gid, name, ok, detail=""): auto.append(dict(id=gid, name=name, status="PASS" if ok else "FAIL", detail=detail))
