c, o = sh("shasum -a 256 -c runs/RUNS_SHA256SUMS_20261124_expansion_prep.txt"); gate("A3", "previous 142-file index: only files regenerated by me may differ", "FAILED" not in o or o.count("FAILED") <= 0, o.strip().split("\n")[-1][:120] if "FAILED" in o else "all match")
c, o = sh(f"{PY} src/check_execution_config.py"); gate("A4", "frozen v1f + execution config (19 checks)", "ALL CONFIG CHECKS PASSED" in o)
