gate("A6", "ledger reconciles: 75 calls / 74 apps / 26 baseline / 100 total / groups 28+2+39+6", R["gemini_calls_total_minimum"] == 75 and R["apps_with_a_new_gemini_call"] == 74 and R["apps_with_existing_baseline_record"] == 26 and R["calls_by_group"] == {"A_v1f_frozen": 28, "B_neo4j_optionB": 2, "C_expansion": 39, "D_identity_gated": 6} and len({a["registry_id"] for a in L["apps"]}) == 100)
suites = {}
for name, cmd in (("eval_score", f"{PY} -W error tests/test_eval_score.py"), ("eval_agreement", f"{PY} -W error tests/test_eval_agreement.py"), ("verify_v2", f"{PY} -W error tests/test_verify_v2.py"), ("pass2_pilot", f"{PY} -W error tests/test_pass2_pilot.py"), ("quota_plan", f"{PY} -W error tests/test_quota_plan.py"), ("eval_seal", f"{PY} -W error tests/test_eval_seal.py"),
                  ("runner_v1f", f"{PY} tests/test_runner_v1f.py {tempfile.mkdtemp()}"), ("neo4j_surfaces", f"{PY} tests/test_neo4j_surfaces.py {tempfile.mkdtemp()}")):
    c, o = sh(cmd); m = re.search(r"Ran (\d+) tests", o); suites[name] = dict(ok=("OK" in o and "FAIL" not in o.replace("FAILED (", "X")) if m else ("ALL SELFTESTS PASSED" in o or "NEO4J TESTS PASSED" in o) and "FAIL " not in o, tests=int(m.group(1)) if m else o.count("PASS "))
gate("A7", "offline test suites (regression; synthetic data; NOT evidence of accuracy)", all(v["ok"] for v in suites.values()), json.dumps({k: v["tests"] for k, v in suites.items()}))
dr = {}
for name, cmd, needle in (("v1f", f"{PY} src/run_p1.py --run p1-v1f-gemini-20261124 --dry-run", "no network"), ("neo4j_optionB", f"{PY} src/run_neo4j_surfaces.py --dry-run", "no model call"), ("neo4j_retrieval", f"{PY} src/neo4j_retrieval.py --dry-run", "NO external call"), ("verifier_v2", f"{PY} src/verify_v2.py --out runs/_gng --records 'baseline/p1_v1/pass1/*.json' --dry-run", "no model call"), ("pass2_pilot", f"{PY} src/pass2_pilot.py dry-run", "no model call")):
    c, o = sh(cmd); dr[name] = needle in o and c == 0
sh("rm -rf runs/_gng"); gate("A8", "dry runs make no network/model call (v1f, Neo4j, Neo4j retrieval, verifier, pilot)", all(dr.values()), json.dumps(dr))
c, o = sh(f"{PY} src/eval_seal_check.py"); gate("A9", "human-eval blind sheets empty + clean; 0 labels", "SEALED (all empty and clean): True" in o)
c, o = sh(f"{PY} src/secret_audit.py"); gate("A10", "secret audit: no key value outside .env", "EXACT key values found outside .env: none" in o)
it = json.load(open("runs/pass2-pilot-plan-v1-20261124/stage1_items.json")); gate("A11", "Pass 2 pilot items built: 4 replays + 12 negative + 12 positive controls; stage-2 sheet blank", len(it["S1b_negative_controls"]) == 12 and len(it["S1c_positive_controls"]) == 12 and len(it["S1a_replays"]) == 4)
t = json.load(open("runs/quota-checks-v1-20261124/limits_observed_gemini_TEMPLATE.json")); gate("A12", "quota templates are BLANK (limits not assumed) and the planner refuses blanks", all(v["rpd"] is None for v in t["models"].values()))
